{
  "name": "Zaber电动定位台",
  "name_en": "Zaber motorized positioning stage",
  "manufacturer": "Zaber Technologies",
  "description": "这是一类可通过串行 ASCII 协议控制的电动定位设备，通常为单轴或多轴位移台。设备可执行回零、绝对位移、相对位移、恒速运动和停止，适用于实验室中的光学元件、样品或探针的精密定位、扫描和对准。",
  "description_en": "This is a motorized positioning device, typically a single-axis or multi-axis stage, controlled over a serial ASCII protocol. It supports homing, absolute moves, relative moves, constant-velocity motion, and stopping, and is used in laboratories for precise positioning, scanning, and alignment of optics, samples, or probes.",
  "tag_hints": [
    "motorized stage",
    "precision positioning",
    "multi-axis motion control",
    "optical alignment",
    "sample positioning",
    "serial ASCII control"
  ],
  "actions": [
    {
      "action_name": "auto-axis",
      "description": "选择指定运动轴",
      "description_en": "select a specific motion axis"
    },
    {
      "action_name": "auto-send",
      "description": "发送原始ASCII命令到设备",
      "description_en": "send a raw ASCII command to the device"
    },
    {
      "action_name": "auto-poll_until_idle",
      "description": "等待设备或指定轴空闲",
      "description_en": "wait until the device or selected axis becomes idle"
    },
    {
      "action_name": "auto-home",
      "description": "执行回零",
      "description_en": "home the stage"
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到绝对位置",
      "description_en": "move to an absolute position"
    },
    {
      "action_name": "auto-move_rel",
      "description": "按相对距离移动",
      "description_en": "move by a relative distance"
    },
    {
      "action_name": "auto-move_vel",
      "description": "以设定速度连续运动",
      "description_en": "move continuously at a specified velocity"
    },
    {
      "action_name": "auto-stop",
      "description": "停止运动",
      "description_en": "stop motion"
    },
    {
      "action_name": "auto-get_status",
      "description": "获取运动状态",
      "description_en": "get motion status"
    },
    {
      "action_name": "auto-encode",
      "description": "将命令编码为ASCII报文",
      "description_en": "encode a command into an ASCII message"
    },
    {
      "action_name": "auto-write",
      "description": "向串行连接写入命令",
      "description_en": "write a command to the serial connection"
    },
    {
      "action_name": "auto-read",
      "description": "从串行连接读取设备回复",
      "description_en": "read a device reply from the serial connection"
    },
    {
      "action_name": "auto-flush",
      "description": "清空串行通信缓冲区",
      "description_en": "flush the serial communication buffer"
    },
    {
      "action_name": "auto-timeout",
      "description": "设置通信超时时间",
      "description_en": "define communication timeout"
    },
    {
      "action_name": "auto-baudrate",
      "description": "设置串口波特率",
      "description_en": "define serial baud rate"
    }
  ]
}

